  const cols = (b, r = {}) => ({ bg_no: b.bgNo ?? r.bg_no, bg_type: b.bgType ?? r.bg_type, contract_id: 'contractId' in b ? b.contractId : r.contract_id, partner_id: 'partnerId' in b ? b.partnerId : r.partner_id, advance_id: 'advanceId' in b ? b.advanceId : r.advance_id, bank_id: 'bankId' in b ? b.bankId : r.bank_id, bank_name: b.bankName ?? r.bank_name, original_paise: 'amount' in b ? paise(b.amount) : r.original_paise, issue_date: b.issueDate ?? r.issue_date, expiry_date: b.expiryDate ?? r.expiry_date, claim_expiry: 'claimExpiry' in b ? b.claimExpiry : r.claim_expiry, linked_type: b.linkedType ?? r.linked_type ?? 'CONTRACT', linked_id: 'linkedId' in b ? b.linkedId : r.linked_id, linked_ref: 'linkedRef' in b ? b.linkedRef : r.linked_ref, margin_bp: 'marginPct' in b ? bp(b.marginPct) : r.margin_bp ?? 0, commission_bp: 'commissionPct' in b ? bp(b.commissionPct) : r.commission_bp ?? 0 });
  const checkLinks = (actor, pj, c) => { if (c.contract_id && !db.prepare('SELECT 1 FROM ctr_contracts WHERE id = ? AND company_id = ? AND org_project_id = ? AND deleted_at IS NULL').get(rid(c.contract_id), actor.companyId, pj)) fail([{ field: 'contractId', message: 'Not a contract of this project' }]); if (c.partner_id && !db.prepare('SELECT 1 FROM mdm_partners WHERE id = ? AND company_id = ? AND deleted_at IS NULL').get(rid(c.partner_id), actor.companyId)) fail([{ field: 'partnerId', message: 'Not a partner of this company' }]); if (c.advance_id && !db.prepare('SELECT 1 FROM ctr_advances WHERE id = ? AND company_id = ? AND deleted_at IS NULL').get(rid(c.advance_id), actor.companyId)) fail([{ field: 'advanceId', message: 'Not an advance of this company' }]); if (c.bank_id && !db.prepare('SELECT 1 FROM mdm_banks WHERE id = ?').get(rid(c.bank_id))) fail([{ field: 'bankId', message: 'Not a bank of the bank master' }]); };
