    update(actor, id, b) { const r = iflow.row(actor, id, 'ctr.insurance.edit'); if (!iflow.EDITABLE.includes(r.status)) throw conflict('An approved policy is not changed; renew it.'); if (b.rowVersion && b.rowVersion !== r.version) throw conflict('Someone changed this; reload it.'); const c = iCols(b, r); if (c.valid_to <= c.valid_from) fail([{ field: 'validTo', message: 'The policy ends before it starts' }]); const k = Object.keys(c); db.prepare(`UPDATE ctr_insurances SET ${k.map((x) => `${x} = ?`).join(', ')}, updated_by = ?, updated_at = ?, version = version + 1 WHERE id = ?`).run(...Object.values(c).map((v) => (v === undefined ? null : v)), actor.user, nowIso(), r.id); audit(actor, 'ctr_insurances', r.id, 'update', r.company_id); return insurances.get(actor, r.id); },
    remove: (actor, id) => iflow.remove(actor, id), submit(actor, id) { iflow.submit(actor, id); return insurances.get(actor, id); }, withdraw: (actor, id, b) => { iflow.withdraw(actor, id, b); return insurances.get(actor, id); }, cancel: (actor, id, b) => { iflow.cancel(actor, id, b); return insurances.get(actor, id); },
